from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

source = Path('products/services/accessible-document-paid-pilot/raw/find-a-tender-search.html')
base = 'https://www.find-tender.service.gov.uk/'
class NoticeLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current = None
        self.links = {}
    def handle_starttag(self, tag, attrs):
        if tag != 'a':
            return
        url = urlsplit(urljoin(base, dict(attrs).get('href') or ''))
        if url.scheme == 'https' and url.netloc == 'www.find-tender.service.gov.uk' and re.fullmatch(r'/Notice/\d+-\d{4}/?', url.path, re.I):
            self.current = (base.rstrip('/') + url.path.rstrip('/'), [])
    def handle_data(self, data):
        if self.current:
            self.current[1].append(data)
    def handle_endtag(self, tag):
        if tag == 'a' and self.current:
            url, chunks = self.current
            title = ' '.join(' '.join(chunks).split())[:250]
            if title and len(title) > len(self.links.get(url, '')):
                self.links[url] = title
            self.current = None

raw = source.read_bytes()
parser = NoticeLinks()
parser.feed(raw.decode('utf-8', errors='replace'))
terms = re.compile(r'accessib|remediat|document|epub|pdf|html', re.I)
links = sorted(parser.links.items(), key=lambda item: -len(terms.findall(item[1])))
result = {'source': str(source), 'source_sha256': hashlib.sha256(raw).hexdigest(), 'purpose': 'Search-result leads only. Confirm the purchased scope, deadline and terms from the original notice.', 'notice_link_count': len(links), 'links': [{'url': url, 'title': title} for url, title in links[:12]]}
out = source.parent.parent / 'notice-link-shortlist.json'
out.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'notice_link_count': len(links), 'top_links': result['links'][:3]}, ensure_ascii=False))
